import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 90 · ANGLE: kindness on Christmas Eve, repaid years later (pregnant stranger in a snowstorm)

sc("""Sweetheart, on Christmas Eve of nineteen eighty-three, a girl of about seventeen knocked on my door in a blizzard, nine months pregnant, with no coat and blood on her lip. She said, please, ma'am, can I use your phone? Somebody's after me. Every sensible person I knew told me afterward that I should have shut that door. I didn't. And that baby was born on my living room floor at two in the morning.""",
   "pregnant teenage girl at door in blizzard", "PLEASE, MA'AM")
sc("""Tonight I'm going to tell you who was after her, what happened that night, and who rang my doorbell twenty years later, on Christmas Eve of two thousand three. Stay with me, honey, because I've only told this story a handful of times. It still makes my hands shake. And the ending is the most beautiful thing that's ever happened in my house.""",
   "woman's hands shaking holding photograph", "TWENTY YEARS LATER")

ch("The blizzard")
sc("""That Christmas Eve, Harold was stuck at his brother's farm in Shelby, twenty miles away, because the roads had closed. Susan was away at nursing school, and Mark was snowed in at a friend's house across town. So it was just me, alone in the house on Maple Drive, with the radio on and a pot of chili on the stove, watching the snow pile up against the windows. The worst blizzard in ten years.""",
   "snow piling against window at night", "THE WORST IN TEN YEARS")
sc("""At ten o'clock, somebody pounded on the back door. Not the front, the back, which nobody ever used. I turned on the porch light, and there was a girl, honey, a skinny girl in a thin sweater, with snow in her hair and her belly so big she had to hold onto the railing. Her lip was split, and she kept looking back over her shoulder into the dark.""",
   "girl on back porch in snow porch light", "SHE KEPT LOOKING BACK")
sc("""She said, please, can I use your phone? I need to call somebody. He's looking for me. And I asked, who's looking for you? And she said, my boyfriend. He's in the car on the next street. He's been drinking. I ran. In a minute I'll tell you what that man did when he found out where she was.""",
   "car with headlights on snowy dark street", "HE'S IN THE CAR")

ch("The door")
sc("""I'll be honest with you, sweetheart. For one second, I was scared. I was a woman alone. And there was a drunk man in a car somewhere out there in the snow. But I looked at that girl, shaking on my porch, holding her belly with both hands, and I thought about my own daughter. And I said, get in here, honey. Now. And I locked the door behind her and turned off the porch light.""",
   "woman pulling girl inside locking door", "GET IN HERE")
sc("""Her name was Angela. She was seventeen. She'd run away from home in Kentucky with this man a year before, and he'd brought her up to Ohio, and things had gone bad. Very bad. That night, he'd hit her in the car, and she'd jumped out at a stop sign and run through the backyards in the snow until she saw my kitchen light. Mine was the only one on.""",
   "kitchen light glowing in dark snowy night", "MINE WAS THE ONLY LIGHT")
sc("""I wrapped her in Harold's big flannel robe, put her by the stove, and gave her a bowl of chili. And then I called the sheriff. The deputy said, ma'am, every road in the county is closed. We'll get someone there when we can. Keep your doors locked. And that's when we heard the car, honey. Driving slowly down Maple Drive, with its headlights sweeping across the houses.""",
   "headlights sweeping across houses at night", "THE CAR WAS SLOWLY COMING")

ch("The man")
sc("""If you're enjoying Grandma's story, tap the like button for me, sweetheart. It helps more people find these stories. The car stopped in front of my house. A man got out and started walking up my front steps, yelling her name. Angela! Angela, I know you're in there! And he pounded on the front door so hard the pictures on my wall rattled. Angela crawled under my kitchen table.""",
   "man pounding on front door at night", "I KNOW YOU'RE IN THERE")
sc("""I want you to know, honey, I was terrified. But I went to that door, and I didn't open it. I said through the door, as loud and steady as I could, the sheriff is on his way. There's nobody here for you. And then I said the thing my mother always told me to say to a bully. I said, go home, young man, before you do something you can't take back.""",
   "elderly woman speaking firmly through door", "GO HOME, YOUNG MAN")
sc("""Then I did something I'd never done before. I went and got Harold's deer rifle out of the closet. It wasn't loaded. I didn't even know where he kept the bullets. But I stood in my front window with that rifle, where he could see me through the glass. He looked at me for a long minute. Then he got back in his car and drove off into the snow. And I sat down on the floor, because my legs gave out.""",
   "woman silhouette in window at night", "I STOOD IN THE WINDOW")

sc("""Angela came out from under the table, white as a sheet, and we sat together by the stove for two hours, honey, listening to every car. She told me about her mother back in Kentucky, whom she hadn't called in a year because she was ashamed. I said, sweetheart, your mother isn't ashamed of you. She's scared to death. And I dialed the number for her. But by then, the line was dead.""",
   "young woman and older woman by stove at night", "SHE'S SCARED TO DEATH")
ch("Two in the morning")
sc("""And then, at about midnight, Angela grabbed my arm, and said, Mrs. Miller, I think something's wrong. Her water had broken, honey, right there on my kitchen floor. And the roads were closed, and the phone lines were down by then, and there was nobody in the world but me. I'd had two babies of my own. But I had never, ever delivered one.""",
   "frightened young woman in labor kitchen", "HER WATER BROKE")
sc("""So I did what women have done for ten thousand years. I boiled water, because that's what they do in the movies, though I never figured out what it was for. I got every clean towel in the house. I made a bed of blankets in front of the stove in the living room. And I held Angela's hand, and I told her about my own two babies, every minute of it, over and over, to keep her calm.""",
   "blankets by woodstove in dim living room", "TEN THOUSAND YEARS")
sc("""At two in the morning on Christmas Day, nineteen eighty-three, a baby girl was born on my living room floor, in front of the stove, by the light of the Christmas tree. Seven pounds, I'd guess. Loud and pink and perfect. I wrapped her in my mother's Christmas tablecloth, because it was the cleanest thing I had, and I laid her on Angela's chest. And we both cried.""",
   "newborn baby wrapped in tablecloth by Christmas tree", "BORN ON CHRISTMAS DAY")

ch("Christmas morning")
sc("""So far, the blizzard, the back door, the man, and the baby. At eight in the morning, the snowplow came through, and the ambulance right behind it. The paramedics checked them both and said they were fine. One of them looked at me and said, ma'am, you did everything right. Where'd you learn that? And I said, honey, I didn't. I just didn't have a choice.""",
   "ambulance on snowy street morning", "YOU DID EVERYTHING RIGHT")
sc("""Before they put her in the ambulance, Angela asked me my first name. I said, Ruth. And she said, then that's her name. Ruth Noelle, because she was born on Christmas. And then they were gone. Harold came home at noon, and I told him everything, and he sat down at the kitchen table and didn't say anything for a long time. Then he said, Ruthie, the rifle wasn't loaded. I said, I know.""",
   "ambulance driving away in snow", "RUTH NOELLE")
sc("""The man was arrested two days later, honey, in a bar in Mansfield. He'd been in trouble before. He went to prison for four years. Angela's mother came up from Kentucky and took her and the baby home. Angela sent me one letter that spring, with a picture of little Ruth Noelle. And then life went on, and I didn't hear from her again. For twenty years.""",
   "old letter with baby photograph", "ONE LETTER")

sc("""And every Christmas Eve after that, honey, I'd think about that girl and that baby, and wonder. Did she get away from him for good? Was the baby healthy? Did she grow up knowing she was loved? I said a prayer for little Ruth Noelle every Christmas morning at two o'clock, because I'd wake up at that hour every year, like clockwork, for the rest of my life.""",
   "elderly woman awake at night by Christmas tree", "AT TWO O'CLOCK EVERY YEAR")
sc("""Harold's brother told me once that I'd been a fool to open that door. He said, Ruth, that man could've killed you both. And maybe he was right, sweetheart. But I've thought about it for forty years, and I'd open it again tonight. Some doors you open because you're brave. Some you open because you know you couldn't live with yourself if you didn't.""",
   "back door with porch light on in snow", "I'D OPEN IT AGAIN")
ch("Twenty years later")
sc("""On Christmas Eve, two thousand three, Harold and I were sitting by the fire, two old people, when the doorbell rang. It was snowing again, not like that night, just a gentle snow. And on my porch stood a woman about forty, with a young woman beside her. Tall, dark-haired, in a nurse's coat, with a little name tag pinned to it. The name tag said, Ruth N. Carter, R.N.""",
   "two women on snowy porch Christmas Eve", "THE NAME TAG")
sc("""Angela said, Mrs. Miller, do you remember me? And I didn't even answer, sweetheart. I just pulled them both inside and held them. Ruth Noelle was twenty years old, and she was a nurse, in the labor and delivery ward at a hospital in Lexington, Kentucky. She said, Mama told me the story every Christmas. About the lady who delivered me on her living room floor. I wanted to do the same.""",
   "young nurse hugging elderly woman", "I WANTED TO DO THAT")

ch("What she brought")
sc("""And then she handed me a box. Inside, folded neatly, was my mother's Christmas tablecloth. The one I'd wrapped her in. Angela had kept it for twenty years, washed and pressed. And on top of it was a little book, a nurse's notebook. Ruth Noelle said, Mrs. Miller, I've delivered sixty-three babies this year. I write every one of their names in here. Because of you.""",
   "folded Christmas tablecloth and small notebook", "SIXTY-THREE BABIES")
sc("""Angela told me the rest at my kitchen table. She'd gone home, finished high school, and become a social worker. She'd spent fifteen years running a shelter for women in Kentucky. Women like she'd been, running through the snow with nowhere to go. She said, Mrs. Miller, there's a sign over our door. It says, the light is always on. That's from you.""",
   "women's shelter door with sign light on", "THE LIGHT IS ALWAYS ON")

ch("Grandma's lesson")
sc("""They've come every Christmas Eve since, honey. Ruth Noelle has three children of her own now, and she's the head nurse of her whole ward. And every Christmas Eve, I leave my kitchen light on all night long. Harold used to tease me about the electric bill. I'd tell him, somebody might need it. You never know who's out there in the dark, looking for the one light that's on.""",
   "kitchen window light on at night snow", "LEAVE YOUR LIGHT ON")
sc("""Tell me in the comments, sweetheart. Would you have opened that back door? Be honest with Grandma. And if anyone ever opened their door for you when you needed it, I want to hear about it. There are more of my family's stories in the playlist right there on your screen, and I'll see you in the next one. Good night, honey. Leave your light on.""",
   "house with one lit window in snowy night", "WOULD YOU OPEN IT?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma90", "A Pregnant Stranger Knocked on Christmas Eve. 20 Years LATER...",
     ["Grandma Ruth is a fictional narrator, and this is a fictional story. All names are invented.",
      "If you or someone you know is experiencing domestic violence in the U.S., the National Domestic Violence Hotline is 1-800-799-7233."],
     "kindness repaid story", minutes=(12, 14.5), voice="en_US-lessac-high")
